const cfg = $('Set - Config').first().json;
const requirement = $('HTTP Request - Fetch ClickUp Requirement Details').first().json;
const response = $input.first().json;

const textBlock = (response.content || []).find(b => b.type === 'text');
let parsed = { clarityScore: 0, acceptanceCriteria: [], openQuestions: ['Could not parse Claude response'], summary: '' };
try {
  const raw = (textBlock?.text || '{}').replace(/```json|```/g, '').trim();
  parsed = JSON.parse(raw);
} catch (e) {
  parsed.parseError = true;
}

return [{
  json: {
    ...cfg,
    requirementName: requirement.name || '',
    requirementDescription: requirement.description || requirement.text_content || '',
    requirementAnalysis: parsed
  }
}];

const prior = $('JS - Parse Requirement Analysis').first().json;
const response = $input.first().json;

const textBlock = (response.content || []).find(b => b.type === 'text');
let parsed = { affectedServices: [], dataModelChanges: [], apiChanges: [], riskNotes: ['Could not parse Claude response'], architectureSummary: '' };
try {
  const raw = (textBlock?.text || '{}').replace(/```json|```/g, '').trim();
  parsed = JSON.parse(raw);
} catch (e) {
  parsed.parseError = true;
}

return [{ json: { ...prior, architecture: parsed } }];

const prior = $('JS - Parse Architecture Output').first().json;
const response = $input.first().json;

const textBlock = (response.content || []).find(b => b.type === 'text');
let parsed = { tasks: [] };
try {
  const raw = (textBlock?.text || '{}').replace(/```json|```/g, '').trim();
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { tasks: [], parseError: true };
}

const tasks = parsed.tasks && parsed.tasks.length ? parsed.tasks : [{ title: 'Implement: ' + prior.requirementName, description: prior.architecture.architectureSummary, estimateHours: 4 }];

// Fan out: one item per subtask, each carrying the full accumulated state
// so Aggregate can fold it back into a single item afterward.
return tasks.map(t => ({
  json: {
    ...prior,
    taskBreakdown: tasks,
    subtaskTitle: t.title,
    subtaskDescription: t.description,
    subtaskEstimateHours: t.estimateHours
  }
}));

// Collapse the fanned-out subtask items back into one feature-level item
// using the last pre-fanout state (which already has the full task list).
const state = $('JS - Parse Task Breakdown & Fan Out Subtasks').first().json;
return [{ json: { ...state } }];

const state = $('JS - Rebuild Single Feature-Level State').first().json;
const ciResult = $input.first().json;

const testsPassed = ciResult.conclusion === 'success' || ciResult.status === 'passed' || ciResult.passed === true;
const attempt = (state.implementationAttempt || 0) + (testsPassed ? 0 : 1);

return [{
  json: {
    ...state,
    testsPassed,
    testFailureLog: ciResult.failureLog || ciResult.summary || '',
    implementationAttempt: attempt,
    branch: ciResult.branch || state.branch
  }
}];

