const state = $('JS - Carry PR Details Forward').first().json;
const scan = $input.first().json;
const findings = scan.findings || [];
const criticalOrHigh = findings.filter(f => /critical|high/i.test(f.severity || ''));

return [{
  json: {
    ...state,
    securityFindings: findings,
    criticalOrHighCount: criticalOrHigh.length,
    securityPassed: criticalOrHigh.length === 0
  }
}];

