const state = $('IF - Approved').first().json;
const metrics = $input.first().json;

const errorRate = Number(metrics.errorRatePercent ?? metrics.error_rate ?? 0);
const p95LatencyMs = Number(metrics.p95LatencyMs ?? metrics.latency_p95 ?? 0);
const uptimePercent = Number(metrics.uptimePercent ?? metrics.uptime ?? 100);

const healthy = errorRate < 1 && p95LatencyMs < 800 && uptimePercent >= 99.5;

return [{
  json: {
    ...state,
    errorRate,
    p95LatencyMs,
    uptimePercent,
    productionHealthy: healthy
  }
}];

